/* Palette: #1a1a2e (bg), #16213e (card), #e94560 (accent), #f5f5f5 (text), #0f3460 (highlight) */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: 'Courier New', monospace;
  font-size: 18px;
  color: #f5f5f5;
  padding: 16px;
}
.card {
  background: #16213e;
  border: 4px solid #e94560;
  border-radius: 0;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 #0f3460;
}
h1 {
  font-size: 24px;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #e94560;
}
.question {
  font-size: 28px;
  font-weight: bold;
  margin-bottom: 24px;
  min-height: 40px;
}
.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}
.answer-btn, .ctrl-btn {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 28px;
  border: 3px solid #f5f5f5;
  background: #0f3460;
  color: #f5f5f5;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-width: 80px;
}
.answer-btn:hover, .ctrl-btn:hover {
  background: #e94560;
  border-color: #e94560;
}
.answer-btn:focus-visible, .ctrl-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 3px;
}
.answer-btn:active, .ctrl-btn:active {
  transform: translate(2px, 2px);
}
.answer-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}
.score-line {
  font-size: 20px;
  margin-bottom: 24px;
}
#score {
  font-weight: bold;
  color: #e94560;
}
.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .question { font-size: 24px; }
  .answer-btn, .ctrl-btn { font-size: 18px; padding: 10px 20px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;

function render() {
  if (current < questions.length) {
    const q = questions[current];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = false;
    answerB.disabled = false;
    answered = false;
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
  scoreEl.textContent = score;
}

function handleAnswer(choice) {
  if (answered || current >= questions.length) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[current].correct) {
    score++;
    scoreEl.textContent = score;
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (current < questions.length) {
    current++;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  answered = false;
  render();
});

render();
